308	// 回滚成功附带的上报沿用序号/重复规则，版本必须等于锁定目标；
309	// 接受后更新当前版本与上报配置与回滚状态，保留期望配置、修订号与审计。
310	func TestRollbackSuccessReportAndShadow(t *testing.T) {
311		s := setupUpgrade(t, "d1")
312		spec := rbSpec()
313		createCampaign(t, s, spec)
314		bringOnline(t, s, "d1")
315		// 先设置期望配置，回滚后不得被升级前/上报配置覆盖。
316		rev, err := s.UpdateDesired("d1", "bob", upBase.Add(-2*time.Minute), 0, json.RawMessage(`{"x":1}`))
