320		awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
321		rb, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
322	
323		bad := func(mut func(*OperationResult)) {
324			t.Helper()
325			r := OperationResult{
326				CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
327				At: upBase.Add(9 * time.Minute), Success: true,
328				Seq: 2, Version: "v1", Config: json.RawMessage(`{"x":2}`),
329			}
330			mut(&r)
331			if err := s.SubmitResult(r); !errors.Is(err, ErrInvalidReport) {
332				t.Fatalf("want ErrInvalidReport, got %v", err)
333			}
334		}
335		bad(func(r *OperationResult) { r.Seq = 0 })
336		bad(func(r *OperationResult) { r.Version = "v2" })
337		bad(func(r *OperationResult) { r.Version = "" })
338		bad(func(r *OperationResult) { r.Config = json.RawMessage(`[]`) })
339		bad(func(r *OperationResult) { r.Seq = 1; r.Config = json.RawMessage(`{"x":9}`) }) // 同序号内容冲突
340	
341		// 所有拒绝都不改影子、活动与历史。
342		view, _ := s.Get("d1")
343		if view.Version != "v1" || view.LastSeq != 1 || view.Revision != 1 {
344			t.Fatalf("shadow changed on rejected rollback: %+v", view)
345		}
346		cv, _ := s.GetCampaign(spec.ID)
347		if findDevice(cv, "d1").Status != DeviceRollingBack {
348			t.Fatalf("campaign changed on rejected rollback: %+v", findDevice(cv, "d1"))
349		}
350		historyBefore := len(cv.Results)
351	
352		// 合法回滚：窗口外、截止前提交。上报配置引入新的 /y 差异。
353		rbAt := upBase.Add(90 * time.Minute)
354		if err := s.SubmitResult(OperationResult{
355			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
356			At: rbAt, Success: true,
357			Seq: 2, Version: "v1", Config: json.RawMessage(`{"x":2,"y":9}`),
358		}); err != nil {
359			t.Fatalf("valid rollback: %v", err)
360		}
361		view, _ = s.Get("d1")
362		if view.Version != "v1" || !view.Online || view.LastSeq != 2 || string(view.Reported) != `{"x":2,"y":9}` {
363			t.Fatalf("shadow after rollback: %+v", view)
364		}
365		// 期望配置、修订号与审计保留。
366		if view.Revision != 1 || string(view.Desired) != `{"x":1}` {
367			t.Fatalf("desired/revision changed: %+v", view)
368		}
369		if auds, _ := s.Audit("d1"); len(auds) != 1 {
