373		// /y 由回滚上报新引入，首次出现时间为回滚上报时间；不拿升级前配置覆盖期望。
374		diffs, _ := s.Diff("d1")
375		got := map[string]DiffEntry{}
376		for _, e := range diffs {
377			got[e.Path] = e
