381		}
382		if dx, ok := got["/x"]; !ok || !dx.Since.Equal(upBase.Add(-2*time.Minute)) {
383			t.Fatalf("/x keeps original since: %+v", got)
384		}
385		if dy, ok := got["/y"]; !ok || !dy.ReportedExists || !dy.Since.Equal(rbAt) {
386			t.Fatalf("/y first appears at rollback time: %+v", got)
387		}
