398	func TestRollbackFailureRequiresReasonAndKeepsShadow(t *testing.T) {
399		s := setupUpgrade(t, "d1")
400		spec := rbSpec()
401		createCampaign(t, s, spec)
402		bringOnline(t, s, "d1")
403		_, failAt := awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
404		rb, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
405	
406		if err := s.SubmitResult(OperationResult{
407			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
408			At: upBase.Add(9 * time.Minute), Success: false,
409		}); !errors.Is(err, ErrInvalidReason) {
410			t.Fatalf("rollback failure needs reason: %v", err)
411		}
412		rbFailAt := upBase.Add(10 * time.Minute)
413		if err := s.SubmitResult(OperationResult{
414			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
415			At: rbFailAt, Success: false, Reason: "rb boom",
416		}); err != nil {
417			t.Fatalf("rollback failure: %v", err)
418		}
419		v, _ := s.Get("d1")
420		if v.Version != "v1" || v.LastSeq != 1 {
421			t.Fatalf("shadow must not change on rollback failure: %+v", v)
422		}
423		cv, _ := s.GetCampaign(spec.ID)
424		d := findDevice(cv, "d1")
425		if d.Status != DeviceRollbackFailed || d.Phase != StageRollback ||
426			d.RollbackReason != "rb boom" || !d.RollbackAt.Equal(rbFailAt) {
427			t.Fatalf("rollback failure record: %+v", d)
428		}
429		// 安装失败与回滚结果的原因/时间可分别查看。
430		if d.InstallFailReason != "install broken" || !d.InstallFailAt.Equal(failAt) {
431			t.Fatalf("install failure kept separately: %+v", d)
432		}
433		if !d.RollbackResult || d.RollbackSuccess {
434			t.Fatalf("rollback result flags: %+v", d)
435		}
436		if !cv.Ended || cv.Status != CampaignFailed {
437			t.Fatalf("campaign: %+v", cv)
438		}
439	}
