441	// 回滚幂等、冲突与未领取规则。
442	func TestRollbackIdempotencyConflictUnclaimed(t *testing.T) {
443		s := setupUpgrade(t, "d1")
444		spec := rbSpec()
445		createCampaign(t, s, spec)
446		bringOnline(t, s, "d1")
447		inID, _ := awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
448	
449		// 提交未领取的回滚操作：报错且不改状态。
450		if err := s.SubmitResult(OperationResult{
451			CampaignID: spec.ID, DeviceID: "d1", OperationID: "cmp-1:d1:rollback",
452			At: upBase.Add(8 * time.Minute), Success: false, Reason: "early",
453		}); !errors.Is(err, ErrOperationNotClaimed) {
454			t.Fatalf("unclaimed rollback: %v", err)
455		}
456		// 重复提交同一安装失败：不再产生回滚，不增加历史。
457		cv, _ := s.GetCampaign(spec.ID)
458		n := len(cv.Results)
459		if err := s.SubmitResult(OperationResult{
460			CampaignID: spec.ID, DeviceID: "d1", OperationID: inID,
461			At: upBase.Add(40 * time.Minute), Success: false, Reason: "install broken",
462		}); err != nil {
463			t.Fatalf("duplicate install failure: %v", err)
464		}
465		cv, _ = s.GetCampaign(spec.ID)
466		if len(cv.Results) != n || findDevice(cv, "d1").Status != DeviceAwaitingRollback {
467			t.Fatalf("duplicate install failure altered state: %+v", cv)
468		}
469	
470		// 领取回滚并提交失败。
471		rb, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
472		if err := s.SubmitResult(OperationResult{
473			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
474			At: upBase.Add(9 * time.Minute), Success: false, Reason: "rb boom",
475		}); err != nil {
476			t.Fatalf("rollback failure: %v", err)
477		}
478		// 相同结果重复提交：成功但不增加历史。
479		if err := s.SubmitResult(OperationResult{
480			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
481			At: upBase.Add(60 * time.Minute), Success: false, Reason: "rb boom",
482		}); err != nil {
483			t.Fatalf("duplicate rollback result: %v", err)
484		}
485		cv, _ = s.GetCampaign(spec.ID)
486		if len(cv.Results) != n+1 {
487			t.Fatalf("duplicate rollback added history: %+v", cv.Results)
488		}
489		// 改成不同结果（失败改成功）：冲突且不改状态。
490		if err := s.SubmitResult(OperationResult{
491			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
492			At: upBase.Add(61 * time.Minute), Success: true,
493			Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
494		}); !errors.Is(err, ErrResultConflict) {
495			t.Fatalf("changed rollback result: %v", err)
496		}
497		if d := findDevice(mustGetCampaign(s, spec.ID), "d1"); d.Status != DeviceRollbackFailed {
498			t.Fatalf("state changed after conflict: %+v", d)
499		}
