502	// 到达原截止时间：等待/正在回滚的设备以回滚阶段超时结束，不改写影子；
503	// 不再接收新结果；已接受结果的重复提交仍有效。
504	func TestRollbackDeadlineTimeout(t *testing.T) {
505		s := setupUpgrade(t, "d1", "d2")
506		spec := upSpec()
507		spec.Devices = []string{"d1", "d2"}
508		spec.BatchSize = 2
509		spec.RollbackOnFailure = true
510		createCampaign(t, s, spec)
511		bringOnline(t, s, "d1")
512		bringOnline(t, s, "d2")
513	
514		// d1 领取回滚并成功；d2 安装失败后停在等待回滚。
515		awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
516		rb1, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
517		rb1At := upBase.Add(9 * time.Minute)
518		if err := s.SubmitResult(OperationResult{
519			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb1.ID,
520			At: rb1At, Success: true,
521			Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
522		}); err != nil {
523			t.Fatalf("d1 rollback: %v", err)
524		}
525		awaitRollback(t, s, spec, "d2", upBase.Add(12*time.Minute))
526		// d2 领取回滚但不完成（正在回滚）。
527		rb2, _ := s.Claim(spec.ID, "d2", upBase.Add(20*time.Minute))
528	
529		if err := s.AdvanceCampaign(spec.ID, upBase.Add(2*time.Hour)); err != nil {
530			t.Fatal(err)
531		}
532		v, _ := s.GetCampaign(spec.ID)
533		if !v.Ended || v.Status != CampaignFailed {
534			t.Fatalf("deadline ends campaign failed: %+v", v)
535		}
536		d2 := findDevice(v, "d2")
537		if d2.Status != DeviceRollbackTimeout || d2.Phase != StageRollback || d2.Reason == "" {
538			t.Fatalf("rolling-back device rollback-timeout: %+v", d2)
539		}
540		d1 := findDevice(v, "d1")
541		if d1.Status != DeviceRollbackSucceeded {
542			t.Fatalf("finished rollback kept: %+v", d1)
543		}
544		// 影子不被超时改写。
545		if sh, _ := s.Get("d2"); sh.Version != "v1" || sh.LastSeq != 1 {
546			t.Fatalf("shadow changed on timeout: %+v", sh)
547		}
548		// 不再接收新结果。
549		if err := s.SubmitResult(OperationResult{
550			CampaignID: spec.ID, DeviceID: "d2", OperationID: rb2.ID,
551			At: upBase.Add(2*time.Hour + time.Minute), Success: true,
552			Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
553		}); !errors.Is(err, ErrCampaignEnded) {
554			t.Fatalf("new rollback result after deadline: %v", err)
555		}
556		// 已接受结果的重复提交仍有效，不增加历史。
557		n := len(v.Results)
558		if err := s.SubmitResult(OperationResult{
559			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb1.ID,
560			At: upBase.Add(3 * time.Hour), Success: true,
561			Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
562		}); err != nil {
563			t.Fatalf("accepted result replay after end: %v", err)
564		}
565		if cv, _ := s.GetCampaign(spec.ID); len(cv.Results) != n {
566			t.Fatal("replay after deadline added history")
567		}
568	}
