570	// 回滚未完成时的普通上报只更新影子，不替代回滚结果或清除待办；
571	// 回滚最终仍必须恢复到锁定版本。
572	func TestPlainReportDuringRollbackOnlyUpdatesShadow(t *testing.T) {
573		s := setupUpgrade(t, "d1")
574		spec := rbSpec()
575		createCampaign(t, s, spec)
576		bringOnline(t, s, "d1")
577		awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
578	
579		// 等待回滚期间普通上报把版本/配置改成别的：影子更新，回滚待办不变。
580		if err := s.Report("d1", 2, upBase.Add(6*time.Minute), "v-stray", json.RawMessage(`{"a":1}`)); err != nil {
581			t.Fatal(err)
582		}
583		if sh, _ := s.Get("d1"); sh.Version != "v-stray" || sh.LastSeq != 2 {
584			t.Fatalf("plain report should update shadow: %+v", sh)
585		}
586		cv, _ := s.GetCampaign(spec.ID)
587		d := findDevice(cv, "d1")
588		if d.Status != DeviceAwaitingRollback || d.RollbackTarget != "v1" || d.RollbackResult {
589			t.Fatalf("plain report must not clear rollback todo: %+v", d)
590		}
591		w, _ := s.GetDeviceWork("d1")
592		if w.Pending == nil || w.Pending.Kind != StageRollback || w.PendingClaimed ||
593			w.Pending.TargetVersion != "v1" {
594			t.Fatalf("rollback todo survives plain report: %+v", w)
595		}
596		// 回滚成功以更大序号、锁定版本 v1 接受：影子回到锁定版本与上报配置。
597		rb, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute))
598		if err := s.SubmitResult(OperationResult{
599			CampaignID: spec.ID, DeviceID: "d1", OperationID: rb.ID,
600			At: upBase.Add(9 * time.Minute), Success: true,
601			Seq: 3, Version: "v1", Config: json.RawMessage(`{"a":0}`),
602		}); err != nil {
603			t.Fatalf("rollback to locked target: %v", err)
604		}
605		if sh, _ := s.Get("d1"); sh.Version != "v1" || sh.LastSeq != 3 || string(sh.Reported) != `{"a":0}` {
606			t.Fatalf("shadow restored to locked target: %+v", sh)
607		}
608	}
