	}
	if err := s.Report("dev-1", 7, base, "1.1", json.RawMessage(`{"a":2}`)); err != nil {
		t.Fatal(err)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}

	s2, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s2.Close()
	v, err := s2.Get("dev-1")
	if err != nil {
		t.Fatal(err)
	}
	if !v.Online || v.Version != "1.1" || v.Revision != 1 || v.LastSeq != 7 {
		t.Fatalf("restored view: %+v", v)
