459		res := OperationResult{CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
460			At: upBase.Add(5 * time.Minute), Success: true}
461		if err := s.SubmitResult(res); err != nil {
462			t.Fatal(err)
463		}
464		v1, _ := s.GetCampaign(spec.ID)
465		// 相同结果重复提交：成功，不增加历史（即使时间更晚）
466		res.At = upBase.Add(10 * time.Minute)
467		if err := s.SubmitResult(res); err != nil {
468			t.Fatalf("duplicate result: %v", err)
469		}
