471		if len(v2.Results) != len(v1.Results) {
472			t.Fatal("duplicate result added history")
473		}
474		// 改用不同结果：冲突
475		res.Success = false
476		res.Reason = "changed mind"
477		if err := s.SubmitResult(res); !errors.Is(err, ErrResultConflict) {
478			t.Fatalf("conflict: %v", err)
479		}
480		// 跳过阶段：直接提交尚未领取的安装
481		in := "cmp-1:d1:install"
482		if err := s.SubmitResult(OperationResult{
483			CampaignID: spec.ID, DeviceID: "d1", OperationID: in,
484			At: upBase.Add(11 * time.Minute), Success: true,
485		}); !errors.Is(err, ErrOperationNotClaimed) {
486			t.Fatalf("skip stage: %v", err)
487		}
488		// 提交其他设备的操作标识
489		if err := s.SubmitResult(OperationResult{
490			CampaignID: spec.ID, DeviceID: "d2", OperationID: dl.ID,
491			At: upBase.Add(12 * time.Minute), Success: true,
492		}); !errors.Is(err, ErrOperationNotFound) {
493			t.Fatalf("other device op: %v", err)
494		}
495		if err := s.SubmitResult(OperationResult{
496			CampaignID: spec.ID, DeviceID: "d2", OperationID: "cmp-1:d2:download",
497			At: upBase.Add(12 * time.Minute), Success: true,
498		}); !errors.Is(err, ErrOperationNotClaimed) {
499			t.Fatalf("unclaimed own op: %v", err)
