484	// setupInstallFailure 构造下载成功、安装失败已接受（等待回滚）的状态。
485	func setupInstallFailure(t *testing.T, rollback bool) (*Store, string, CampaignSpec, *Operation) {
486		t.Helper()
487		s := setupUpgrade(t, "d1")
488		spec := upSpec()
489		spec.Devices = []string{"d1"}
490		spec.RollbackOnFailure = rollback
491		createCampaign(t, s, spec)
492		bringOnline(t, s, "d1")
493		dl, err := s.Claim(spec.ID, "d1", upBase)
494		if err != nil {
495			t.Fatalf("claim download: %v", err)
496		}
497		if err := s.SubmitResult(OperationResult{
498			CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
499			At: upBase.Add(time.Minute), Success: true,
500		}); err != nil {
501			t.Fatalf("download: %v", err)
502		}
503		in, err := s.Claim(spec.ID, "d1", upBase.Add(2*time.Minute))
504		if err != nil {
505			t.Fatalf("claim install: %v", err)
506		}
507		if err := s.SubmitResult(OperationResult{
508			CampaignID: spec.ID, DeviceID: "d1", OperationID: in.ID,
509			At: upBase.Add(3 * time.Minute), Success: false, Reason: "install boom",
510		}); err != nil {
511			t.Fatalf("install failure: %v", err)
512		}
513		return s, s.dir, spec, &Operation{ID: operationID(spec.ID, "d1", StageRollback)}
514	}
515	
516	// TestResultHistorySuccessWithExtraReasonReopen 提交成功结果时附带了非空原因
517	// （提交路径不拒绝）：原因只存在操作结果上、不进入历史，重开不得误判为矛盾。
518	func TestResultHistorySuccessWithExtraReasonReopen(t *testing.T) {
519		s := setupUpgrade(t, "d1")
520		spec := upSpec()
521		spec.Devices = []string{"d1"}
522		createCampaign(t, s, spec)
523		bringOnline(t, s, "d1")
524		dl, err := s.Claim(spec.ID, "d1", upBase)
525		if err != nil {
526			t.Fatal(err)
527		}
528		// 成功结果携带原因：被接受，历史记录不含原因。
529		if err := s.SubmitResult(OperationResult{
530			CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
531			At: upBase.Add(time.Minute), Success: true, Reason: "informational note",
532		}); err != nil {
533			t.Fatalf("success result with reason must be accepted: %v", err)
534		}
535		dir := s.dir
536		s.Close()
537		s2, err := Open(dir)
538		if err != nil {
539			t.Fatalf("success op result carrying a reason must not break history check: %v", err)
540		}
541		defer s2.Close()
542		cv := mustGetCampaign(s2, spec.ID)
543		if findDevice(cv, "d1").Status != DeviceReady || len(cv.Results) != 1 || cv.Results[0].Reason != "" {
544			t.Fatalf("view: %+v", cv.Results)
545		}
546	}
547	
548	// TestResultHistoryTimezoneEqualInstant 历史时间与操作结果时间是同一时刻、
549	// 仅时区表示不同（Z vs +08:00）时不得判为冲突。
